import React from "react";
import { useCart } from "./CartContext";

const Cart = () => {
    const { cart, addToCart, removeFromCart, updateQuantity, totalItems, totalPrice } = useCart();

    return (
        <div className="container">
            <h2>Giỏ Hàng</h2>
            <div className="cart-items">
                {cart.length === 0 ? (
                    <p>Giỏ hàng của bạn trống.</p>
                ) : (
                    cart.map((product) => (
                        <div key={product.id} className="cart-item d-flex align-items-center">
                            <img src={product.image} alt={product.name} className="product-image" />
                            <div className="cart-item-details">
                                <h5>{product.name}</h5>
                                <p>{product.description}</p>
                                <div className="d-flex align-items-center">
                                    <button
                                        className="btn btn-secondary mx-2"
                                        onClick={() => updateQuantity(product.id, "decrease")}
                                    >
                                        -
                                    </button>
                                    <span>{product.quantity}</span>
                                    <button
                                        className="btn btn-secondary mx-2"
                                        onClick={() => updateQuantity(product.id, "increase")}
                                    >
                                        +
                                    </button>
                                </div>
                                <p className="price">
                                    Giá: {product.price} VND
                                </p>
                            </div>
                            <button
                                className="btn btn-danger"
                                onClick={() => removeFromCart(product.id)}
                            >
                                Xóa
                            </button>
                        </div>
                    ))
                )}
            </div>
            {cart.length > 0 && (
                <div className="cart-summary">
                    <h3>Tổng Số Lượng: {totalItems}</h3>
                    <h4>Tổng Tiền: {totalPrice} VND</h4>
                </div>
            )}
        </div>
    );
};

export default Cart;
